// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 seed, address actor, uint256 gap) public {
        // keep params in the admissible domain (wide)
        bytes32 g = bytes32(seed);
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        gap = bound(gap, 0, 100);

        // lock a guess at some future block
        vm.roll(block.number + 1 + gap);
        vm.deal(actor, 1 ether);
        uint256 target = block.number + 1;
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        // move far past the target block so blockhash(target) == 0,
 // and fund the contract so a win is actually payable
        vm.roll(block.number + 300);
        vm.deal(address(c), 5 ether);

        uint256 balBefore = actor.balance;
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        // GENERAL RULE: the guesser can only ever receive the 2 ether payout
        // when his locked hash is keccak256(blockhash(target block)) — never
        // when it merely equals the raw blockhash.
        assertTrue(
            !(ok && actor.balance - balBefore == 2 ether)
                || g == keccak256(abi.encodePacked(blockhash(target))),
            "payout happened without hash == keccak256(blockhash)"
        );
    }
}
